var EXPORTS={fringeSpacing:fringeSpacing, brightPosition:brightPosition, firstMinAngle:firstMinAngle, singleSlitIntensity:singleSlitIntensity};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WaveOpticsForgePure = EXPORTS; }
